  <title>Computer Languages Quiz</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0d1117;
      --panel: #161b22;
      --panel-strong: #1f2937;
      --text: #f0f6fc;
      --muted: #9da7b3;
      --accent: #7c3aed;
      --accent-strong: #a78bfa;
      --border: #30363d;
      --focus: #58a6ff;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      background:
        radial-gradient(circle at top left, rgba(124, 58, 237, 0.32), transparent 32rem),
        radial-gradient(circle at bottom right, rgba(88, 166, 255, 0.18), transparent 28rem),
        var(--bg);
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      line-height: 1.5;
    }

    .quiz-app {
      width: min(100% - 2rem, 56rem);
      margin: 0 auto;
      padding: 4rem 0;
    }

    .quiz-card {
      background: rgba(22, 27, 34, 0.9);
      border: 1px solid var(--border);
      border-radius: 1.5rem;
      box-shadow: 0 1.5rem 4rem rgba(0, 0, 0, 0.42);
      overflow: hidden;
    }

    .quiz-header {
      padding: 2rem;
      background: linear-gradient(135deg, rgba(124, 58, 237, 0.28), rgba(88, 166, 255, 0.1));
      border-bottom: 1px solid var(--border);
    }

    h1 {
      margin: 0 0 0.75rem;
      font-size: clamp(2rem, 5vw, 3.25rem);
      line-height: 1.1;
    }

    .intro,
    .help-text {
      color: var(--muted);
      margin: 0;
    }

    .quiz-form {
      padding: 2rem;
    }

    .form-field {
      margin: 0 0 1.5rem;
      padding: 1.5rem;
      background: var(--panel-strong);
      border: 1px solid var(--border);
      border-radius: 1rem;
    }

    .form-field legend {
      padding: 0;
      margin-bottom: 0.5rem;
      color: var(--text);
      font-size: 1.2rem;
      font-weight: 750;
    }

    .choice-list {
      display: grid;
      gap: 0.75rem;
      margin-top: 1rem;
    }

    .choice {
      display: flex;
      gap: 0.75rem;
      align-items: flex-start;
      min-height: 3rem;
      padding: 0.85rem 1rem;
      background: #0f172a;
      border: 1px solid var(--border);
      border-radius: 0.85rem;
      cursor: pointer;
      transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
    }

    .choice:hover {
      background: #111c33;
      border-color: var(--accent-strong);
      transform: translateY(-1px);
    }

    .choice input {
      width: 1.2rem;
      height: 1.2rem;
      margin-top: 0.15rem;
      accent-color: var(--accent);
      flex: 0 0 auto;
    }

    .choice:has(input:focus-visible) {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    .choice:has(input:checked) {
      background: rgba(124, 58, 237, 0.2);
      border-color: var(--accent-strong);
    }

    .submit-row {
      display: flex;
      justify-content: flex-end;
      margin-top: 2rem;
    }

    button {
      min-height: 3rem;
      padding: 0.85rem 1.4rem;
      border: 0;
      border-radius: 999px;
      background: linear-gradient(135deg, var(--accent), #2563eb);
      color: white;
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      box-shadow: 0 0.75rem 1.75rem rgba(37, 99, 235, 0.32);
    }

    button:hover {
      filter: brightness(1.08);
    }

    button:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 4px;
    }

    @media (max-width: 38rem) {
      .quiz-app {
        width: min(100% - 1rem, 56rem);
        padding: 0.5rem 0;
      }

      .quiz-header,
      .quiz-form {
        padding: 1.25rem;
      }

      .form-field {
        padding: 1rem;
      }

      .submit-row,
      button {
        width: 100%;
      }
    }
  </style>
</head>
