       color: var(--muted);
       margin: 0;
     }

     .quiz-form {
       padding: 2rem;
     }

     .form-field {
       margin: 0 0 1.5rem;
       padding: 1.5rem;
       background: var(--panel-strong);
       border: 1px solid var(--border);
       border-radius: 1rem;
     }

     .question-title {
       margin: 0 0 0.5rem;
       color: var(--text);
