       cursor: pointer;
       box-shadow: 0 0.75rem 1.75rem rgba(37, 99, 235, 0.32);
     }

     button:hover {
       filter: brightness(1.08);
     }

     button:focus-visible {
       outline: 3px solid var(--focus);
       outline-offset: 4px;
     }

     @media (max-width: 38rem) {
       .quiz-app {
         width: min(100% - 1rem, 56rem);
         padding: 0.5rem 0;
