         padding: 1rem;
       }

       .submit-row,
       button {
         width: 100%;
       }
     }
   </style>
 </head>
 <body>
   <div id="root"></div>

   <script>
     const quizQuestions = [
       {
         name: "programming-languages",
         prompt: "Which of these are commonly used programming languages?",
         helpText: "Select all options that are recognized programming languages used to write software.",
         choices: ["Python", "JavaScript", "HTML", "Java"]
       },
       {
         name: "web-languages",
         prompt: "Which languages are often associated with web development?",
         choices: ["JavaScript", "CSS", "SQL", "TypeScript"]
       },
       {
         name: "systems-languages",
         prompt: "Which languages are known for systems programming?",
         choices: ["C", "Rust", "Go", "Ruby"]
       }
     ];

     function toKebabCase(value) {
       return value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
     }

     function Choice({ questionName, label }) {
       const value = toKebabCase(label);
       return `
         <label class="choice">
           <input type="checkbox" name="${questionName}" value="${value}">
           <span>${label}</span>
         </label>
       `;
     }

     function QuizQuestion({ question, index }) {
       const questionId = `question-${index + 1}`;
       const helpId = question.helpText ? `${questionId}-help` : "";
       const describedBy = helpId ? ` aria-describedby="${helpId}"` : "";

       return `
         <div class="form-field" role="group" aria-labelledby="${questionId}-title"${describedBy}>
           <h2 class="question-title" id="${questionId}-title">${index + 1}. ${question.prompt}</h2>
           ${question.helpText ? `<p id="${helpId}" class="help-text">${question.helpText}</p>` : ""}
           <div class="choice-list">
             ${question.choices.map((label) => Choice({ questionName: question.name, label })).join("")}
           </div>
         </div>
       `;
     }

     function QuizApp({ questions }) {
       return `
         <main class="quiz-app">
           <section class="quiz-card" aria-labelledby="quiz-title">
             <header class="quiz-header">
               <h1 id="quiz-title">Computer Languages Quiz</h1>
               <p class="intro">Choose every answer that applies. Some questions have more than one correct choice.</p>
             </header>

             <form class="quiz-form" aria-describedby="quiz-instructions">
               <p id="quiz-instructions" class="help-text">Each question supports multiple selections.</p>
               ${questions.map((question, index) => QuizQuestion({ question, index })).join("")}
               <div class="submit-row">
                 <button type="submit">Submit quiz</button>
               </div>
             </form>
           </section>
         </main>
       `;
     }

     document.getElementById("root").innerHTML = QuizApp({ questions: quizQuestions });
   </script>
 </body>
 </html>

